const getProductByCode = (code) => productsCatalog.find(p => p.id === code);
const getProductsByCategory = (category) => productsCatalog.filter(p => p.category === category);
const getFeaturedProducts = () => productsCatalog.filter(p => p.isFeatured);
const getTrendingProducts = () => productsCatalog.filter(p => p.isTrending);

module.exports = { productsCatalog, getProductByCode, getProductsByCategory, getFeaturedProducts, getTrendingProducts };